 * Character-level scanning primitives shared by the header and value
 * parsers: the cursor over a single line, name/string decoding, and bare
 * value-token classification.
 */

export class ParseError extends Error {
  constructor(lineNo, reason) {
    super(`line ${lineNo}: ${reason}`)
    this.lineNo = lineNo
    this.reason = reason
  }
}

export class Cursor {
  constructor(line, lineNo) {
    this.s = line
    this.i = 0
    this.lineNo = lineNo
  }

  fail(reason) {
    throw new ParseError(this.lineNo, reason)
  }

  /**
   * Skips spaces and tabs. If what follows is a comment marker outside a
   * quoted string, the rest of the line is dropped: the cursor is left at
   * the end of the line, since a `#`/`;` there ends it.
   */
  skipWs() {
    while (this.i < this.s.length && (this.s[this.i] === ' ' || this.s[this.i] === '\t')) this.i++
    if (this.i < this.s.length && (this.s[this.i] === '#' || this.s[this.i] === ';')) {
      this.i = this.s.length
    }
  }

  atEnd() {
    this.skipWs()
    return this.i >= this.s.length
  }
}

const NAME_CHAR = /[A-Za-z0-9_-]/

export function parseName(cur) {
  cur.skipWs()
  if (cur.i >= cur.s.length) cur.fail('expected a name')
  const c = cur.s[cur.i]
  if (c === '"' || c === "'") return parseString(cur)
  const start = cur.i
  while (cur.i < cur.s.length && NAME_CHAR.test(cur.s[cur.i])) cur.i++
  if (cur.i === start) cur.fail('expected a name')
  return cur.s.slice(start, cur.i)
}

export function parseDottedName(cur) {
  const names = [parseName(cur)]
  while (true) {
    cur.skipWs()
    if (cur.i < cur.s.length && cur.s[cur.i] === '.') {
      cur.i++
      names.push(parseName(cur))
    } else {
      break
    }
  }
  return names
}

export function parseString(cur) {
  const quote = cur.s[cur.i]
  cur.i++
  if (quote === "'") {
    const start = cur.i
    while (cur.i < cur.s.length && cur.s[cur.i] !== "'") cur.i++
    if (cur.i >= cur.s.length) cur.fail('unterminated string')
    const text = cur.s.slice(start, cur.i)
    cur.i++
    return text
  }
  let out = ''
  while (true) {
    if (cur.i >= cur.s.length) cur.fail('unterminated string')
    const ch = cur.s[cur.i]
    if (ch === '"') {
      cur.i++
      return out
    }
    if (ch === '\\') {
      cur.i++
      if (cur.i >= cur.s.length) cur.fail('unterminated string')
      const esc = cur.s[cur.i]
      if (esc === '"') { out += '"'; cur.i++ }
      else if (esc === '\\') { out += '\\'; cur.i++ }
      else if (esc === 'n') { out += '\n'; cur.i++ }
      else if (esc === 't') { out += '\t'; cur.i++ }
      else if (esc === 'r') { out += '\r'; cur.i++ }
      else if (esc === '0') { out += '\0'; cur.i++ }
      else if (esc === 'u') {
        cur.i++
        const hex = cur.s.slice(cur.i, cur.i + 4)
        if (hex.length < 4) cur.fail('unterminated string')
        if (!/^[0-9A-Fa-f]{4}$/.test(hex)) cur.fail('invalid escape \\u')
        out += String.fromCharCode(parseInt(hex, 16))
        cur.i += 4
      } else {
        cur.fail(`invalid escape \\${esc}`)
      }
    } else {
      out += ch
      cur.i++
    }
  }
}

const INT_RE = /^[+-]?\d+(_\d+)*$/
const FLOAT_RE = /^[+-]?\d+(_\d+)*(\.\d+(_\d+)*)?([eE][+-]?\d+(_\d+)*)?$/

function normalizeInteger(token) {
  const cleaned = token.replace(/_/g, '')
  const negative = cleaned[0] === '-'
  const digits = cleaned.replace(/^[+-]/, '')
  const big = BigInt(digits)
  return (negative ? -big : big).toString()
}

function normalizeFloat(token) {
  return Number(token.replace(/_/g, ''))
}

export function classifyBareToken(token, cur) {
  if (token === 'true') return { kind: 'boolean', value: true }
  if (token === 'false') return { kind: 'boolean', value: false }
  if (INT_RE.test(token)) return { kind: 'integer', value: normalizeInteger(token) }
  if (FLOAT_RE.test(token) && /[.eE]/.test(token)) return { kind: 'float', value: normalizeFloat(token) }
  cur.fail(`invalid value ${token}`)
}
"}

