  cur.skipWs()
  if (cur.i >= cur.s.length) cur.fail('expected a value')
  const c = cur.s[cur.i]
  if (c === ',' || c === ']' || c === '}') cur.fail('expected a value')
  if (c === '"' || c === "'") return { kind: 'string', value: parseString(cur) }
