  while (true) {
    cur.skipWs()
    if (cur.i >= cur.s.length) cur.fail('unterminated array')
    if (cur.s[cur.i] === ']') { cur.i++; break }
    items.push(parseValue(cur, path.concat([{ idx }])))
    idx++
    cur.skipWs()
    if (cur.i >= cur.s.length) cur.fail('unterminated array')
    if (cur.s[cur.i] === ',') { cur.i++; continue }
    if (cur.s[cur.i] === ']') { cur.i++; break }
    cur.fail('trailing text after a value')
  }
