function parseInlineTable(cur, path) {
  cur.i++
  const table = makeTable()
  cur.skipWs()
  if (cur.i < cur.s.length && cur.s[cur.i] === '}') { cur.i++; return table }
  if (cur.i >= cur.s.length) cur.fail('unterminated inline table')
  while (true) {
    const names = parseDottedName(cur)
    cur.skipWs()
    if (cur.i >= cur.s.length || cur.s[cur.i] !== '=') cur.fail('expected = in an inline table')
    cur.i++
    const { parent, leaf, leafPath } = assignInto(table, path, names, cur)
    parent.entries.set(leaf, parseValue(cur, leafPath))
    cur.skipWs()
    if (cur.i >= cur.s.length) cur.fail('unterminated inline table')
    if (cur.s[cur.i] === ',') {
      cur.i++
      cur.skipWs()
      if (cur.i >= cur.s.length) cur.fail('unterminated inline table')
      continue
    }
    if (cur.s[cur.i] === '}') { cur.i++; break }
    cur.fail('trailing text after a value')
  }
  return table
}

function processHeader(doc, names, arrayHeader, cur) {
  const { node: parent, path: parentPath } = walkIntermediate(doc.root, [], names.slice(0, -1), cur)
  const leaf = names[names.length - 1]
  const leafPath = parentPath.concat([leaf])
  let entry = parent.entries.get(leaf)
