    if (!entry) {
      entry = { kind: 'arraytable', value: [] }
      parent.entries.set(leaf, entry)
    } else if (entry.kind !== 'arraytable') {
      cur.fail(`${formatPath(leafPath)} is not an array of tables`)
    }
    const fresh = makeTable()
    entry.value.push(fresh)
    doc.current = fresh
    doc.currentPath = leafPath.concat([{ idx: entry.value.length - 1 }])
  } else {
    if (!entry) {
      entry = makeTable()
      entry.headerDefined = true
      parent.entries.set(leaf, entry)
    } else if (entry.kind === 'table') {
      if (entry.headerDefined) cur.fail(`table ${formatPath(leafPath)} is defined twice`)
      entry.headerDefined = true
    } else {
      cur.fail(`${formatPath(leafPath)} is not a table`)
    }
    doc.current = entry
    doc.currentPath = leafPath
  }
}

function parseHeaderLine(doc, cur) {
  let arrayHeader = false
  cur.i++
  if (cur.s[cur.i] === '[') { arrayHeader = true; cur.i++ }
  const names = parseDottedName(cur)
  cur.skipWs()
  if (cur.i >= cur.s.length || cur.s[cur.i] !== ']') cur.fail('unterminated table header')
  cur.i++
  if (arrayHeader) {
    if (cur.i >= cur.s.length || cur.s[cur.i] !== ']') cur.fail('unterminated table header')
    cur.i++
  }
  cur.skipWs()
  if (cur.i < cur.s.length) cur.fail('trailing text after a table header')
  processHeader(doc, names, arrayHeader, cur)
}

function parseAssignmentLine(doc, cur) {
  const names = parseDottedName(cur)
  cur.skipWs()
  if (cur.i >= cur.s.length || cur.s[cur.i] !== '=') cur.fail('expected key = value')
  cur.i++
  const { parent, leaf, leafPath } = assignInto(doc.current, doc.currentPath, names, cur)
  const val = parseValue(cur, leafPath)
  cur.skipWs()
  if (cur.i < cur.s.length) cur.fail('trailing text after a value')
  parent.entries.set(leaf, val)
}

function firstSignificant(line) {
  const idx = line.search(/[^ \t]/)
  if (idx === -1) return -1
  const c = line[idx]
  if (c === '#' || c === ';') return -1
  return idx
}

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  const doc = { root: makeTable(), current: null, currentPath: [] }
  doc.current = doc.root
  for (let ln = 0; ln < lines.length; ln++) {
    const line = lines[ln].endsWith('\r') ? lines[ln].slice(0, -1) : lines[ln]
    const lineNo = ln + 1
    const idx = firstSignificant(line)
    if (idx === -1) continue
    const cur = new Cursor(line, lineNo)
    cur.i = idx
    if (line[idx] === '[') parseHeaderLine(doc, cur)
    else parseAssignmentLine(doc, cur)
  }
  return doc.root
}
