 * Renders a parsed document tree as canonical JSON or as a flat `keys`
 * listing.
 */

import { formatPath } from './parser.js'

function sortedKeys(table) {
  return [...table.entries.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
}

function jsonValue(node, indent) {
  switch (node.kind) {
    case 'table': {
      const keys = sortedKeys(node)
      if (keys.length === 0) return '{}'
      const inner = indent + '  '
      const members = keys.map(
        (k) => `${inner}${JSON.stringify(k)}: ${jsonValue(node.entries.get(k), inner)}`
      )
      return `{\n${members.join(',\n')}\n${indent}}`
    }
    case 'array':
    case 'arraytable': {
      if (node.value.length === 0) return '[]'
      const inner = indent + '  '
      const items = node.value.map((v) => `${inner}${jsonValue(v, inner)}`)
      return `[\n${items.join(',\n')}\n${indent}]`
    }
    case 'string':
      return JSON.stringify(node.value)
    case 'boolean':
      return node.value ? 'true' : 'false'
    case 'integer':
      return node.value
    case 'float':
      return JSON.stringify(node.value)
    default:
      throw new Error(`unknown node kind ${node.kind}`)
  }
}

export function toJSON(root) {
  return jsonValue(root, '') + '\n'
}

const TYPE_NAMES = {
  table: 'table',
  array: 'array',
  arraytable: 'array',
  string: 'string',
  integer: 'integer',
  float: 'float',
  boolean: 'boolean',
}

function childrenOf(node) {
  if (node.kind === 'table') {
    return sortedKeys(node).map((k) => [k, node.entries.get(k)])
  }
  if (node.kind === 'array' || node.kind === 'arraytable') {
    return node.value.map((v, i) => [{ idx: i }, v])
  }
  return []
}

function walkKeys(node, path, out) {
  for (const [seg, child] of childrenOf(node)) {
    const childPath = path.concat([seg])
    out.push(`${formatPath(childPath)} ${TYPE_NAMES[child.kind]}`)
    walkKeys(child, childPath, out)
  }
}

export function toKeys(root) {
  const out = []
  walkKeys(root, [], out)
  return out.length === 0 ? '' : out.join('\n') + '\n'
}
"}

